<?php
declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; methodOnly('POST'); safeApi(function():void{$db=apiDatabase();$i=jsonRequest();$email=inputString($i,'email',true);if(!filter_var($email,FILTER_VALIDATE_EMAIL))jsonResponse(false,'Validation failed.',null,['email'=>'Valid email required.'],422);$s=$db->prepare('INSERT INTO enquiries(name,email,phone,subject,message) VALUES(:name,:email,:phone,:subject,:message)');$s->execute([':name'=>inputString($i,'name',true),':email'=>$email,':phone'=>inputString($i,'phone'),':subject'=>inputString($i,'subject'),':message'=>inputString($i,'message',true)]);jsonResponse(true,'Enquiry submitted successfully.',['id'=>(int)$db->lastInsertId()],[],201);});
